const canvasRef = useRef<HTMLDivElement>(null);

const keyboard = useGraphKeyboard({
  nodes, edges, targetRef: canvasRef,
  onCreateNode: (position) => {
    const id = nextId('node', nodes);
    setNodes([...nodes, { id, position, data: { label: 'New' } }]);
    return id;
  },
  onConnect: (source, target) =>
    setEdges([...edges, { id: nextId('edge', edges), source, target }]),
  onDeleteNode: (id) => { … },
});

const layout = useGraphLayout({
  nodes,
  edges,
  defaultMode: 'vertical',
  onNodeMove: (id, position) => setNodes(move(nodes, id, position)),
});

<GraphCanvas>
  {layout.nodes.map((node) => (
    <GraphNode key={node.id} node={node} onMove={layout.onMove}>
      {label(node)}
    </GraphNode>
  ))}
</GraphCanvas>

